const item = $input.item;
const j = item.json;

// ======================================================
// DADOS DE IDENTIFICAÇÃO
// ======================================================

const msg = j.messages?.[0] ?? {};

j.PhoneConnected =
  j.PhoneConnected ??
  j.metadata?.phone_number_id ??
  j.phoneconnect ??
  null;

j.display_phone_number =
  j.display_phone_number ??
  j.metadata?.display_phone_number ??
  null;

j.Phone =
  j.Phone ??
  j.phone ??
  j.contacts?.[0]?.wa_id ??
  msg.from ??
  null;

j.Nome =
  j.Nome ??
  j.contacts?.[0]?.profile?.name ??
  null;

// ======================================================
// GESTOR
// 1 = VX
// 2 = CWC
// 3 = MGF
// ======================================================

const mapaGestor = {
  1: "VX",
  2: "CWC",
  3: "MGF",
};

const gestorCodigo = Number(
  j.gestor_codigo ??
  j.gestorid ??
  j.idgestor ??
  j.gestor ??
  null
);

j.gestor = {
  codigo: Number.isFinite(gestorCodigo) ? gestorCodigo : null,
  nome: mapaGestor[gestorCodigo] ?? null,
};

// ======================================================
// CONFIGURAÇÃO POR NÚMERO CONECTADO
// Cada PhoneConnected possui sua própria configuração.
// ======================================================

const phonesConfig = {
  // ======================================================
  // VX
  // ======================================================
  "1068535889684555": {
    descricao: "integração com o sistema comercial VX",
    gestorPadrao: "VX",

    accessToken: "EAAVf75K5aOkBR7tGs4IEl2LUdlTU4SOX8TvZBnQ8MfS7cMihZBfaThCRdN5sOCZAeeZBWtZBXQpV5F85x57byGy1A6wZC7533qILkvZCZAzdQEsMMDGnvjuRlE4o7NgGQRKZBTFacW7bScHgkNlTPBFvfFLOY022eEcTACZASX31mnn9M4ZBhKzqh9MJBWw2AOoZCCQSXAZDZD",
    businessAccountID: "2387569575073052",

    endpoints: {
      ultimasFaturas:
"https://produtos.agenciavirtual.api.icommercial003.inovamobil.com.br/api/chatbot/faturas-abertas",

      retornarUsuario:
"https://produtos.agenciavirtual.api.icommercial003.inovamobil.com.br/api/chatbot/retornar-usuario",

      gerarFatura:
"https://produtos.agenciavirtual.api.icommercial003.inovamobil.com.br/api/chatbot/fatura-pdf",

      retornardebitos: "https://produtos.faturamento.icommercial003.inovamobil.com.br/api/debitos/listar-debitos-em-abertos",

      webhook: "COLOQUE_AQUI_A_URL_DO_WEBHOOK",
    },

    negociacao: {
      parcelaMinima: 15,
      parcelasMaximasPorFaixa: [
        { ate: 1000, maxParcelas: 24 },
        { ate: 2000, maxParcelas: 30 },
        { ate: 5000, maxParcelas: 40 },
        { ate: 100000, maxParcelas: 60 },
      ],
    },
  },

  // ======================================================
  // CWC
  // ======================================================
  "9999999999999999": {
    descricao: "integração com o sistema comercial SFC",
    gestorPadrao: "CWC",

    accessToken: "COLOQUE_AQUI_O_ACCESS_TOKEN_META_CWC",
    businessAccountID: "2387569575073052",

    endpoints: {
      ultimasFaturas:
"https://produtos.agenciavirtual.api.icommercial003.inovamobil.com.br/api/chatbot/faturas-abertas",

      retornarUsuario:
"https://produtos.agenciavirtual.api.icommercial003.inovamobil.com.br/api/chatbot/retornar-usuario",

      gerarFatura:      "https://produtos.agenciavirtual.api.icommercial003.inovamobil.com.br/api/chatbot/fatura-pdf",

      retornardebitos:       "https://produtos.faturamento.icommercial003.inovamobil.com.br/api/debitos/listar-debitos-em-abertos",

      webhook: "COLOQUE_AQUI_A_URL_DO_WEBHOOK",
    },

    negociacao: {
      parcelaMinima: 15,
      parcelasMaximasPorFaixa: [
        { ate: 1000, maxParcelas: 24 },
        { ate: 2000, maxParcelas: 30 },
        { ate: 5000, maxParcelas: 40 },
        { ate: 100000, maxParcelas: 60 },
      ],
    },
  },
};

// ======================================================
// VALIDAÇÃO DO NÚMERO CONECTADO
// ======================================================

const phoneConnected = String(j.PhoneConnected ?? "")
  .replace(/\D+/g, "");

const phoneConfig = phonesConfig[phoneConnected];

if (!phoneConfig) {
  throw new Error(
    `PhoneConnected (${phoneConnected || "vazio"}) não mapeado em phonesConfig`
  );
}

// ======================================================
// DEFINIÇÃO DO GESTOR
// Se o SELECT não retornar gestor, usa gestorPadrao do número.
// ======================================================

if (!j.gestor.nome && phoneConfig.gestorPadrao) {
  j.gestor = {
    codigo:
      Object.entries(mapaGestor).find(
        ([, nome]) => nome === phoneConfig.gestorPadrao
      )?.[0] ?? null,
    nome: phoneConfig.gestorPadrao,
  };

  if (j.gestor.codigo !== null) {
    j.gestor.codigo = Number(j.gestor.codigo);
  }
}

if (!j.gestor.nome) {
  throw new Error(
    `Gestor (${j.gestor.codigo ?? "vazio"}) não mapeado. Esperado: 1=VX, 2=CWC, 3=MGF`
  );
}

// ======================================================
// API
// ======================================================

j.PhoneConnected = phoneConnected;
j.phoneconnect = phoneConnected;

j.api = {
  AccessToken: phoneConfig.accessToken,
  AcessToken: phoneConfig.accessToken,
  BusinessAccountID: phoneConfig.businessAccountID,

  phone: {
    id: phoneConnected,
    display: j.display_phone_number ?? null,
    descricao: phoneConfig.descricao ?? null,
  },

  gestor: {
    codigo: j.gestor.codigo,
    nome: j.gestor.nome,
  },

  endpoints: {
    ultimasFaturas: phoneConfig.endpoints.ultimasFaturas,
    retornarUsuario: phoneConfig.endpoints.retornarUsuario,
    gerarFatura: phoneConfig.endpoints.gerarFatura,
    retornardebitos: phoneConfig.endpoints.retornardebitos,
    webhook: phoneConfig.endpoints.webhook,
  },
};

// ======================================================
// CONFIGURAÇÕES DE NEGOCIAÇÃO
// ======================================================

j.negociacao = phoneConfig.negociacao ?? {
  parcelaMinima: 15,
  parcelasMaximasPorFaixa: [
    { ate: 1000, maxParcelas: 24 },
    { ate: 2000, maxParcelas: 30 },
    { ate: 5000, maxParcelas: 40 },
    { ate: 100000, maxParcelas: 60 },
  ],
};

return item;

const j = $input.item.json || {};

/**PARAR o bot se:
- Recebeu um evento de status do WhatsApp
OU
- Não existe mensagem do cliente**/

const stopBot =
  !!j.statuses?.length ||
  !j.messages?.length;

return [{
  json: {
    ...j,
    stopBot
  }
}];

const item = $input.item;
const j = item.json;

const msg = j.messages?.[0] ?? {};
const interactive = msg.interactive ?? {};

const flowAtual = String(
  j.flow ??
  j.sessao_banco?.flow ??
  ""
).trim().toUpperCase();

// ======================================================
// DADOS BÁSICOS
// ======================================================

j.message_id = msg.id ?? null;
j.timestamp = msg.timestamp ?? null;
j.message_type = msg.type ?? null;

// ======================================================
// TEXTO
// ======================================================

j.texto = msg.text?.body ?? null;

// ======================================================
// BOTÃO / LISTA
// ======================================================

j.buttonReply = interactive.button_reply ?? null;
j.listReply = interactive.list_reply ?? null;

// ======================================================
// FLAGS
// ======================================================

j.veio_texto = !!j.texto;
j.veio_botao = !!j.buttonReply;
j.veio_lista = !!j.listReply;
j.veio_interactive = j.veio_botao || j.veio_lista;

j.enviou_conteudo =
  !!msg.text ||
  msg.type === "audio" ||
  msg.type === "image" ||
  msg.type === "video" ||
  msg.type === "document" ||
  msg.type === "sticker" ||
  msg.type === "location";

j.recebeu_selecao =
  j.veio_botao ||
  j.veio_lista;

j.recebeu_texto_livre =
  j.enviou_conteudo &&
  !j.recebeu_selecao;

// ======================================================
// RESPOSTA PADRONIZADA
// ======================================================

j.resposta_id =
  j.buttonReply?.id ??
  j.listReply?.id ??
  null;

j.resposta_titulo =
  j.buttonReply?.title ??
  j.listReply?.title ??
  null;

j.resposta_descricao =
  j.listReply?.description ??
  null;

j.resposta_cliente =
  j.resposta_titulo ??
  j.texto ??
  null;

// ======================================================
// NORMALIZAÇÃO
// ======================================================

j.resposta_texto_normalizada = String(j.resposta_cliente ?? "")
  .trim()
  .toUpperCase()
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "");

if (j.resposta_id) {
  j.resposta_normalizada = String(j.resposta_id)
    .trim()
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
} else if (j.recebeu_texto_livre && flowAtual.includes("TEXTO_LIVRE")) {
  j.resposta_normalizada = "TEXTO_LIVRE";
} else {
  j.resposta_normalizada = "";
}

// ======================================================
// QUEBRA DO PADRÃO
// ======================================================

const partes = j.resposta_normalizada.split("_");

j.tipo_resposta = partes[0] || null;
j.numero_fluxo = partes[1] || null;
j.acao_resposta = partes.slice(2).join("_") || null;

// ======================================================
// FLAGS AUXILIARES
// ======================================================

j.respondeu_botao = j.tipo_resposta === "BOTAO";
j.respondeu_lista = j.tipo_resposta === "LISTA";

// ======================================================
// DEBUG
// ======================================================

j.debug_resposta = {
  tipo: j.tipo_resposta,
  fluxo: j.numero_fluxo,
  acao: j.acao_resposta,
  resposta_id: j.resposta_id,
  resposta_titulo: j.resposta_titulo,
  resposta_cliente: j.resposta_cliente,
  resposta_texto_normalizada: j.resposta_texto_normalizada,
  flowAtual
};

return item;

const item = $input.item;
const j = item.json;

function agoraSql() {
  return new Date().toISOString().slice(0, 19).replace("T", " ");
}

function dataFuturaSql(dias) {
  if (!dias) return null;

  const d = new Date();
  d.setDate(d.getDate() + dias);

  return d.toISOString().slice(0, 19).replace("T", " ");
}

const resposta = (j.resposta_normalizada ?? "").trim().toUpperCase();
const acao = (j.acao_resposta ?? "").trim().toUpperCase();

const flowAtual = (
  j.flow ??
  j.sessao_banco?.flow ??
  ""
).trim().toUpperCase();

j.router = {
  origem: resposta,
  flow_anterior: flowAtual,
  proximo_flow: null,
  rota: null,
  motivo: null,
};

function route({ flow, rota, motivo, step, maturidade }) {
  const agora = agoraSql();

  j.router.proximo_flow = flow;
  j.router.rota = rota ?? flow;
  j.router.motivo = motivo;

  j.rota = rota ?? flow;
  j.flow = flow;

  if (step !== undefined) j.step = step;
  if (maturidade !== undefined) j.maturidade = maturidade;

  j.ultimaacao = j.ultimaacao ?? resposta ?? null;
  j.ultimaresposta =
    j.ultimaresposta ??
    j.resposta_cliente ??
    motivo ??
    null;

  j.tentativasnegociacao =
    j.tentativasnegociacao ??
    j.sessao_banco?.tentativasnegociacao ??
    0;

  j.datacriacaosessao =
    j.datacriacaosessao ??
    j.sessao_banco?.datacriacaosessao ??
    agora;

  j.ultimadatasessao = agora;

  return item;
}


// ======================================================
// ENTRADA ESPONTÂNEA / NOVO CONTATO DO CLIENTE
// Usado quando o cliente manda texto livre sem estar em uma coleta obrigatória
// ou após um fluxo conclusivo sem nova interação pendente.
// ======================================================

const textoEntradaEspontanea = String(
  j.texto ??
  j.resposta_cliente ??
  ""
).trim();

const recebeuTextoLivre =
  j.recebeu_texto_livre === true ||
  j.message_type === "text";

const estaEmColetaTexto =
  flowAtual === "AGUARDANDO_CODIGO_LIGACAO" ||
  flowAtual === "AGUARDANDO_DOCUMENTO" ||
  flowAtual === "AGUARDANDO_CPF_CNPJ" ||
  flowAtual === "AGUARDANDO_MOTIVO_RECUSA" ||
  flowAtual === "MOTIVO_RECUSA_PROPOSTA_TEXTO_LIVRE" ||
  flowAtual === "DUVIDA_COBRANCA_TEXTO_LIVRE" ||
  flowAtual === "SOLICITAR_MOTIVO_INADIMPLENCIA_TEXTO_LIVRE" ||
  flowAtual === "AGUARDANDO_MOTIVO_INADIMPLENCIA_TEXTO_LIVRE" ||
  flowAtual === "AGUARDANDO_DADOS_CONSULTA_NEGOCIACAO";

const flowsConclusivosLiberamEntradaEspontanea = [
  "ANALISE_CADASTRAL",
  "AGUARDANDO_APROVACAO",
  "PROPOSTA_ESCOLHIDA",
  "DUVIDA_OUTRO_ASSUNTO_ENCERRADA",
  "NEGOCIACAO_ENCERRADA_RECUSA",
  "NAO_INTERESSE_TEXTO_LIVRE_ENCERRADO",
  "ENCERRAR_COM_RECONTATO",
  "ENCERRAR_COM_ALERTA"
];

const flowPodeAbrirEntradaEspontanea =
  !flowAtual ||
  flowAtual === "FALLBACK" ||
  flowAtual === "NULL" ||
  flowAtual.includes("ENCERRADA") ||
  flowAtual.includes("ENCERRADO") ||
  flowsConclusivosLiberamEntradaEspontanea.includes(flowAtual);

if (
  recebeuTextoLivre &&
  textoEntradaEspontanea &&
  !estaEmColetaTexto &&
  flowPodeAbrirEntradaEspontanea
) {
  j.origemcontato = "ENTRADA_PASSIVA_CLIENTE";
  j.ultimaacao = "ENTRADA_PASSIVA_RETOMADA";
  j.ultimaresposta = textoEntradaEspontanea;

  return route({
    flow: "ENTRADA_ESPONTANEA",
    rota: "ENTRADA_ESPONTANEA",
    motivo: "Cliente iniciou novo contato espontâneo pelo WhatsApp",
    step: 1,
    maturidade: Math.max(j.maturidade ?? 1, 3),
  });
}


// ======================================================
// Tratamento para campos de seleção
// ======================================================

const aguardandoSelecao =
  (j.typeinteration ?? "").toUpperCase() === "SELECAO";

if (
  aguardandoSelecao &&
  j.recebeu_texto_livre
) {
  return route({
    flow: flowAtual,
    rota: "ALERTA_TEXTO_COMPONENTE_SELECAO",
    motivo: "Cliente enviou conteúdo quando havia uma seleção pendente",
    step: j.step,
    maturidade: j.maturidade,
  });
}

// ======================================================
// AUTENTICAÇÃO - CÓDIGO DA LIGAÇÃO
// ======================================================

if (flowAtual === "SOLICITAR_CODIGO_LIGACAO" && j.message_type === "text") {
  const codigoLigacao = String(
    j.texto ??
    j.resposta_cliente ??
    ""
  ).replace(/\D+/g, "");

  if (!codigoLigacao) {
    j.ultimaacao = "CODIGO_LIGACAO_INVALIDO";
    j.ultimaresposta = j.resposta_cliente ?? null;

    return route({
      flow: "CODIGO_LIGACAO_INVALIDO",
      rota: "CODIGO_LIGACAO_INVALIDO",
      motivo: "Cliente não informou um código de ligação válido",
      step: 1,
      maturidade: Math.max(j.maturidade ?? 1, 2),
    });
  }

  j.codigoligacao = codigoLigacao;

  j.ultimaacao = "INFORMOU_CODIGO_LIGACAO";
  j.ultimaresposta = `Código da ligação informado: ${codigoLigacao}`;

  return route({
    flow: "SOLICITAR_CPF_CNPJ",
    rota: "SOLICITAR_CPF_CNPJ",
    motivo: "Cliente informou o código da ligação",
    step: 2,
    maturidade: Math.max(j.maturidade ?? 1, 3),
  });
}

// ======================================================
// AUTENTICAÇÃO - CPF/CNPJ
// ======================================================

if (flowAtual === "SOLICITAR_CPF_CNPJ" && j.message_type === "text") {
  const cpfcnpj = String(
    j.texto ??
    j.resposta_cliente ??
    ""
  ).replace(/\D+/g, "");

  if (![11, 14].includes(cpfcnpj.length)) {
    j.ultimaacao = "CPF_CNPJ_INVALIDO";
    j.ultimaresposta = j.resposta_cliente ?? null;

    return route({
      flow: "CPF_CNPJ_INVALIDO",
      rota: "CPF_CNPJ_INVALIDO",
      motivo: "Cliente não informou CPF/CNPJ válido",
      step: 2,
      maturidade: Math.max(j.maturidade ?? 1, 2),
    });
  }

  j.cpfcnpj = cpfcnpj;

  j.ultimaacao = "INFORMOU_CPF_CNPJ";
  j.ultimaresposta = "Cliente informou CPF/CNPJ para validação";

  return route({
    flow: "VALIDAR_LIGACAO_CPF_CNPJ",
    rota: "VALIDAR_LIGACAO_CPF_CNPJ",
    motivo: "Cliente informou código da ligação e CPF/CNPJ para validação",
    step: 3,
    maturidade: Math.max(j.maturidade ?? 1, 3),
  });
}

// ======================================================
// BOTAO 01 - CAMPANHA INICIAL
// ======================================================

if (resposta === "BOTAO_01_VER_PENDENCIAS") {
    j.codigoligacao = null;
  j.cpfcnpj = null;
  j.ultimaacao = resposta;
  j.ultimaresposta = "Consumidor deseja consultar pendências";

  return route({
    flow: "SOLICITAR_CODIGO_LIGACAO",
    rota: "SOLICITAR_CODIGO_LIGACAO",
    motivo: "Consumidor deseja consultar pendências e precisa autenticar a ligação",
    step: 1,
    maturidade: 3,
  });
}

if (resposta === "BOTAO_01_NAO_INTERESSE") {
  j.ultimaacao = resposta;
  j.ultimaresposta = "Consumidor não deseja consultar pendências";

  return route({
    flow: "NAO_INTERESSE_CONSULTAR_PENDENCIAS",
    rota: "NAO_INTERESSE_CONSULTAR_PENDENCIAS",
    motivo: "Consumidor não deseja consultar pendências",
    step: 1,
    maturidade: 1,
  });
}

// ======================================================
// LISTA 01 - MOTIVO DO NÃO INTERESSE
// ======================================================

if (resposta === "LISTA_01_SEM_CONDICOES_FINANCEIRAS") {
  j.motivoinadimplencia = "SEM_CONDICOES_FINANCEIRAS";
  j.situacaoatual = "AINDA_COM_DIFICULDADES";
  j.objecao = "SEM_CONDICOES_FINANCEIRAS";

  j.ultimaacao = resposta;
  j.ultimaresposta = "Cliente informou que não possui condições financeiras no momento";

  return route({
    flow: "SEM_CONDICOES_FINANCEIRAS",
    rota: "SEM_CONDICOES_FINANCEIRAS",
    motivo: "Cliente informou que não possui condições financeiras no momento",
    step: 1,
    maturidade: 2,
  });
}

if (resposta === "LISTA_01_RESOLVER_FUTURAMENTE") {
  j.objecao = "RESOLVER_FUTURAMENTE";
  j.ultimaacao = resposta;
  j.ultimaresposta = "Cliente pretende resolver futuramente";

  return route({
    flow: "PREVISAO_RETORNO",
    rota: "PREVISAO_RETORNO",
    motivo: "Cliente pretende resolver futuramente",
    step: 1,
    maturidade: 2,
  });
}

if (resposta === "LISTA_01_DUVIDAS_COBRANCA") {
  j.objecao = "DUVIDA_COBRANCA";
  j.ultimaacao = resposta;
  j.ultimaresposta = "Cliente possui dúvidas sobre cobrança";

  return route({
    flow: "DUVIDA_COBRANCA",
    rota: "DUVIDA_COBRANCA",
    motivo: "Cliente possui dúvidas sobre cobrança",
    step: 1,
    maturidade: 3,
  });
}

if (resposta === "LISTA_01_NAO_RESPONSAVEL") {
  j.objecao = "NAO_RESPONSAVEL_LIGACAO";
  j.ultimaacao = resposta;
  j.ultimaresposta = "Cliente informou não ser responsável pela ligação";

  return route({
    flow: "NAO_RESPONSAVEL_LIGACAO",
    rota: "NAO_RESPONSAVEL_LIGACAO",
    motivo: "Cliente informou não ser responsável pela ligação",
    step: 1,
    maturidade: 1,
  });
}

if (resposta === "LISTA_01_OUTRO_MOTIVO") {
  j.objecao = "OUTRO_MOTIVO";
  j.ultimaacao = resposta;
  j.ultimaresposta = "Cliente deseja informar outro motivo";

  return route({
    flow: "OUTRO_MOTIVO_NAO_INTERESSE_CONSULTA_PENDENCIA",
    rota: "OUTRO_MOTIVO_NAO_INTERESSE_CONSULTA_PENDENCIA",
    motivo: "Cliente deseja informar outro motivo",
    step: 1,
    maturidade: 2,
  });
}

// ======================================================
// LISTA 02 - PREVISÃO DE REGULARIZAÇÃO FUTURA
// ======================================================

if (resposta === "LISTA_02_30_DIAS") {
  j.previsaoregularizacao = "ATE_30_DIAS";
  j.previsaoregularizacaodias = 30;
  j.previsaoregularizacaodescricao = "Nos próximos 30 dias";

  j.proximaabordagem_dias = 30;
  j.proximaabordagem = dataFuturaSql(30);

  j.riscoinadimplencia = "MEDIO";
  j.prioridaderecontato = "ALTA";
  j.intencaopagamento = "CURTO_PRAZO";
  j.objecao = "RESOLVER_FUTURAMENTE";

  j.ultimaacao = resposta;
  j.ultimaresposta = "Cliente informou previsão de regularização em até 30 dias";

  return route({
    flow: "ENCERRAR_COM_RECONTATO",
    rota: "ENCERRAR_COM_RECONTATO",
    motivo: "Cliente pretende regularizar nos próximos 30 dias",
    step: 2,
    maturidade: 4,
  });
}

if (resposta === "LISTA_02_30_90_DIAS") {
  j.previsaoregularizacao = "ENTRE_30_90_DIAS";
  j.previsaoregularizacaodias = 60;
  j.previsaoregularizacaodescricao = "Entre 30 e 90 dias";

  j.proximaabordagem_dias = 60;
  j.proximaabordagem = dataFuturaSql(60);

  j.riscoinadimplencia = "ALTO";
  j.prioridaderecontato = "MEDIA";
  j.intencaopagamento = "MEDIO_PRAZO";
  j.objecao = "RESOLVER_FUTURAMENTE";

  j.ultimaacao = resposta;
  j.ultimaresposta = "Cliente informou previsão de regularização entre 30 e 90 dias";

  return route({
