  quantidadeParcelas = Math.min(quantidadeParcelas, parcelasMaximas);
} else {
  quantidadeParcelas =
    capacidadePagamento > 0
      ? Math.ceil(totalAtualizado / capacidadePagamento)
      : parcelasMaximas;

  quantidadeParcelas = Math.min(quantidadeParcelas, parcelasMaximas);
  quantidadeParcelas = Math.max(quantidadeParcelas, 1);
}

